// HasSubscription applies the HasEdge predicate on the "subscription" edge.
func HasSubscription() predicate.MysekaiBirthdaySubscriptionEvent {
	return predicate.MysekaiBirthdaySubscriptionEvent(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, SubscriptionTable, SubscriptionColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasSubscriptionWith applies the HasEdge predicate on the "subscription" edge with a given conditions (other predicates).
func HasSubscriptionWith(preds ...predicate.MysekaiBirthdaySubscription) predicate.MysekaiBirthdaySubscriptionEvent {
	return predicate.MysekaiBirthdaySubscriptionEvent(func(s *sql.Selector) {
		step := newSubscriptionStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

